    },
    {
      "name": "expansion_maturity_stage",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.6,
      "hallucination_observed": true,
      "rationale": "Maturity is directly relevant to expansion focus. However the descriptions rarely state stage; assigning 'established_public_and_large_cap' to 23andMe or 'growth_stage' to a small consultancy is largely inferred beyond text support."
    },
    {
      "name": "geographic_ecosystem_position",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
