    },
    {
      "name": "ecosystem_strategic_role",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Adds a functional role dimension (provider vs capital vs infrastructure) useful for ecosystem mapping. Values align with source (VCs->capital_provider). Some overlap with business_model but not fully redundant."
    },
    {
      "name": "expansion_maturity_signal",
      "analytical_usefulness": 0.15,
      "source_groundedness": 0.55,
