    },
    {
      "name": "silicon_valley_ecosystem_position",
      "analytical_usefulness": 0.1,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Essentially a restatement of geographic_ecosystem_position with identical vocabulary and matching per-row values; trivially redundant, so low usefulness despite being grounded."
    }
